<template>
  <section class="stock-research-graph" aria-label="Company research agent graph"><header><h2>Research agent graph</h2><span>{{ nodes.filter(n=>n.result).length }} / {{ nodes.length }} cases saved</span></header><div class="research-map-toolbar"><label>Area<select v-model="layer" aria-label="Research graph area"><option value="">Company and strategies</option><option value="company">Company research</option><option value="strategy">Strategies</option><option value="followup">Follow-up questions</option></select></label><div class="research-map-legend"><span><i class="for-dot"/>Case for</span><span><i class="against-dot"/>Case against</span><span><i/>Pending</span></div></div>
    <svg v-if="points.length" viewBox="0 0 920 430" role="group" aria-label="Individual company and strategy researchers"><line v-for="pair in pairs" :key="pair.a.id" :x1="pair.a.x" :y1="pair.a.y" :x2="pair.b.x" :y2="pair.b.y" :class="{selected:pair.a.id===selectedId||pair.b.id===selectedId}"/><g v-for="node in points" :key="node.id" :transform="`translate(${node.x},${node.y})`" role="button" tabindex="0" :aria-label="`${node.name}, case ${node.side==='for'?'for':'against'}, ${node.status}`" :aria-pressed="node.id===selectedId" :data-research-agent="node.id" :class="{chosen:node.id===selectedId}" @click="selectedId=node.id" @keydown.enter="selectedId=node.id" @keydown.space.prevent="selectedId=node.id"><title>{{ node.name }} · {{ node.side==='for'?'For':'Against' }}</title><circle class="halo" r="19"/><circle r="14" :fill="!node.result?'#abb4bf':node.side==='for'?'#568d77':'#b47567'"/><text text-anchor="middle" y="4">{{ node.displayNumber }}</text></g></svg>
    <p v-else class="map-empty">Research roles appear as the coordinator assigns them.</p><p class="map-hint">Select a researcher to compare its saved case with the opposing case. Lines pair research on the same question.</p><label class="research-agent-picker">Find a researcher<select v-model="selectedId" aria-label="Find a researcher"><option v-for="node in visible" :key="node.id" :value="node.id">{{ node.name }} · {{ node.side==='for'?'For':'Against' }}</option></select></label>
    <div v-if="selected" class="research-agent-detail"><header><h3>{{ selected.name }} <span>· Case {{ selected.side==='for'?'for':'against' }}</span></h3><small>{{ selected.status }}</small></header><template v-if="selected.result"><article><h4>{{ selected.side==='for'?'Supporting case':'Opposing case' }}</h4><p><StockEvidenceText :text="selected.result.conclusion" :sources="sources"/></p></article><article v-if="other?.result" class="opposing-case"><h4>{{ other.name }} · {{ other.side==='for'?'For':'Against' }}</h4><p><StockEvidenceText :text="other.result.conclusion" :sources="sources"/></p><button @click="selectedId=other.id">Inspect the other researcher →</button></article><details><summary>Strongest alternative and what would change this view</summary><p>{{ selected.result.strongest_other_side }}</p><ul><li v-for="item in selected.result.change_conditions" :key="item">{{ item }}</li></ul></details></template><p v-else class="map-empty">{{ selected.status==='running'?'This researcher is reading the captured evidence.':'No result has been saved by this researcher yet.' }}</p></div>
  </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import StockEvidenceText from './StockEvidenceText.vue'
import {spreadNodes,stockResearchNodes} from '../utils/presentationGraphs.mjs'
const props=defineProps({run:{type:Object,required:true}})
const nodes=computed(()=>stockResearchNodes(props.run)),layer=ref(''),selectedId=ref('')
const sources=computed(()=>props.run.dossier?.sources||[])
const visible=computed(()=>nodes.value.filter(n=>!layer.value||n.layer===layer.value))
const points=computed(()=>spreadNodes(visible.value))
const selected=computed(()=>visible.value.find(n=>n.id===selectedId.value))
const other=computed(()=>nodes.value.find(n=>selected.value&&n.layer===selected.value.layer&&n.area===selected.value.area&&n.side!==selected.value.side))
const pairs=computed(()=>points.value.filter(n=>n.side==='for').map(a=>({a,b:points.value.find(b=>b.area===a.area&&b.layer===a.layer&&b.side==='against')})).filter(x=>x.b))
watch(visible,rows=>{if(!rows.some(n=>n.id===selectedId.value))selectedId.value=rows.find(n=>n.status==='running')?.id||rows.find(n=>n.result)?.id||rows[0]?.id||''},{immediate:true})
</script>
<style scoped>
.stock-research-graph{border:1px solid #f0f3f7;border-radius:12px;background:#f8fafc;overflow:hidden;min-width:0}.stock-research-graph>header{padding:17px 19px 10px;display:flex;justify-content:space-between;gap:15px;align-items:center}.stock-research-graph h2{font-size:18px;font-weight:550;letter-spacing:-.5px;margin:0}.stock-research-graph>header>span{font-size:10px;color:#697589}.research-map-toolbar{padding:0 19px;display:flex;gap:15px;justify-content:space-between;align-items:center;flex-wrap:wrap}.research-map-toolbar label{display:flex;align-items:center;gap:7px;font-size:11px;color:#697589}.research-map-toolbar select,.research-agent-picker select{padding:7px;border:1px solid #e4e9ef;background:#fff;border-radius:6px;font-size:11px;max-width:100%;color:#586a7e}.research-map-legend{display:flex;gap:12px;font-size:10px;color:#697589}.research-map-legend span{display:flex;gap:5px;align-items:center}.research-map-legend i{display:inline-block;width:6px;height:6px;background:#abb4bf;border-radius:50%}.research-map-legend .for-dot{background:#568d77}.research-map-legend .against-dot{background:#b47567}.stock-research-graph>svg{display:block;width:100%;height:290px}.stock-research-graph line{stroke:#dbe3eb;stroke-width:1}.stock-research-graph line.selected{stroke:#e7794c;stroke-width:1.8}.stock-research-graph g[role=button]{cursor:pointer;outline:none}.stock-research-graph .halo{fill:transparent;stroke:transparent;stroke-width:2}.stock-research-graph .chosen .halo,.stock-research-graph g:focus .halo{stroke:#e77848}.stock-research-graph text{font-size:12px;fill:white;pointer-events:none}.map-hint{font-size:11px;line-height:1.7;color:#697589;padding:0 19px 13px;margin:0}.research-agent-picker{display:flex;gap:10px;align-items:center;padding:0 19px 15px;font-size:11px;color:#697589}.research-agent-picker select{min-width:0;flex:1}.research-agent-detail{padding:17px 19px;background:white;border-top:1px solid #e9edf2;max-height:430px;overflow:auto}.research-agent-detail header{display:flex;justify-content:space-between;gap:15px;align-items:start}.research-agent-detail h3{font-size:16px;font-weight:550;margin:0}.research-agent-detail h3 span{color:#697589;font-weight:400;font-size:12px}.research-agent-detail small{font-size:10px;color:#697589}.research-agent-detail article{padding:15px 0;border-bottom:1px solid #edf0f4}.research-agent-detail h4{font-size:11px;font-weight:500;color:#697589;margin:0 0 8px}.research-agent-detail p{font-size:13px;line-height:1.8;color:#52657a;margin:0}.research-agent-detail article button{border:0;background:none;color:#a34b22;font-size:11px;padding:8px 0 0;cursor:pointer}.research-agent-detail details{font-size:12px;margin-top:15px}.research-agent-detail summary{cursor:pointer;color:#697589}.research-agent-detail details p{margin-top:12px}.research-agent-detail ul{padding-left:18px;font-size:12px;line-height:1.8}.map-empty{font-size:13px;color:#697589;padding:24px 19px}@media(max-width:600px){.stock-research-graph>header,.research-map-toolbar{padding-left:13px;padding-right:13px}.stock-research-graph>svg{height:230px}.research-agent-detail{padding:15px 13px}.research-map-legend{gap:9px}.research-agent-picker{padding-left:13px;padding-right:13px}}
</style>
